WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (501::BIGINT, 'Es bastante hipócrita, dice querer ayudar a sus estudiantes y solo ayuda a algunos. No valora que usted vaya mejorando en el curso (lo digo xq en las primeras clases siempre habla de como premia el esfuerzo y que sus estudiantes mejoren). Califica muy duro para la poca materia que da.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec6a9a622ccdf578fb5cb4afb6dea0f5033ba9077226077d487bdfc45f384d91'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Pura Vida, si quiere escuchar historias y divertirse, es con él las clases, se distrae mucho, da explicación de ejercicios fáciles y luego en exámenes o quices son mas difíciles, si lo lleva por primera vez no lo recomiendo y si son varias veces le ayuda con RN2+, hay mejores opciones de profes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, '010d171a0d0fc5dda0fea0e7f89b3e9f86e60f7fe632e71d95b28c116b0e4280'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El mejor profe para los RN. Lit los ayuda a pasar. Sin embargo si hay q ponerle y ser un poco autodidacta. A veces habla mucho y así pero es buena nota y hace bastante practica y quices virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-01-21T00:00:00+00:00'::TIMESTAMPTZ, '5b1d1e988785428fcab5ee03f3c4e86c4346f5eeb5fb319b98a4b42eccdaf329'::TEXT, ARRAY[563, 1018]::BIGINT[]),
    (501::BIGINT, 'El profe es buena gente, pero media clase se pasa contando historias y se mete en temas de política o religión. En clase resuelve ejercicios sencillos, los quizzes son duros (casi todos virtuales) pero califica suave los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'ae2df89025a08b2b0c238300bdffe0831c8b00cb64c17b1a1cffdfcfaea94a7f'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Excelente profe, de los mejores que he tenido en el tec. Hace la clase sencilla lo cual hace que la materia sea más fácil. Como persona es bastante amable y cómico. No suele calificar duro, sin embargo en ciertas situaciones es estricto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a208bfe8a2bdaf250d21bdeadefa82595239169cc0554673c1dbeba8324bf265'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Excelente profe, de los mejores que he conocido. Eso sí, a veces hay que ser autodidacta, porque en clase solo se practica y así, pero igual él resuelve dudas. A veces se distrae, en especial si hay un compañero que distraiga la clase... pero en general muy buen profe, y bueno como persona, excelent'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-04T00:00:00+00:00'::TIMESTAMPTZ, '23a725bd9044f3f7b375cf5a435ad1d318ff26fa128c32ec7893795d86b13741'::TEXT, ARRAY[634, 1018]::BIGINT[]),
    (501::BIGINT, 'Como persona es un 10/10 en todos los sentidos, uno lo llega a ver como un amigo desde el día uno y transmite mucha confianza, Sin embargo a la hora de dar la clase se distrae mucho en especial si tienen un compañero que le lame las..... Si va a llevar un curso muy dificil, no matricule con él.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'a19268c1d36af06b7c3df16cce5a25b1e901c65268862f1c67daae1ebe8d1243'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Sinceramente, es buen profe, nada más debes ser autodidacta, así logré pasar MD. El profe a veces se distrae contando anécdotas y así, pero todo lo q hace lo manda a un grupo, no hace falta copiar, da puntos, deja bastantes quices que ayudan al porcentaje. Recomendado para RN porque los ayuda bastan'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'cd1046b906dcd5edc0d3033a25a2ee144de3d911e3e17c156b6e37cdff3c3f23'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'No lo recomiendo para CDI, es un curso muy pesado y el profe puede pasar hasta 1 hora perdiendo el tiempo contando anécdotas, los quices son demasiado complicados , ayuda a quien va a consulta, póngale y pasa, si se hace amigo de él, algún punto al final le da.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases largas']::TEXT[], '2025-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'dad3700de7440bff661b37e392af2e542923a5b5d75690a01c7c154855a63b98'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Es el mejor profe que he tenido en mi vida. Completamente claro y muy muy divertido. Jamás en su vida haría un comentario inapropiado o despectivo a alguien. Recomendado completamente. *Favor leer con antónimos*'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, 'f65f8a9d17ed76c5d7a378aa514a2dcec3bec99b3d786ca04c1d130185765f68'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Hay que estudiar, las clases suelen ser una de materia y otra de dudas, las anécdotas ayudan a que la clase no sea tan cansada y lo más importante es que no hace falta tomar copiar pq el profe envía todo a un grupo entonces se puede poner mejor atención y entender en vez de solo copiar sin entender'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '2cb14db221a25ae1f5867a6c7cfeacfa0dcb430f1b054cfd35e49268e0719fa5'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Azofeifa ayuda mucho y es buen profe, pero usted tiene que ser autodidacta y sentarse a estudiar por usted mismo, el habla mucho y se pierde demasiado en la materia contando anécdotas, es muy vacilón y ayuda con reclamos de puntos en exámenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-01-14T00:00:00+00:00'::TIMESTAMPTZ, '1c8895a0b56146613b46c6563e93af70e9b3d0cd85ac9f01b512151020fc274e'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Por clase cuenta anécdotas mínimo una hora, hace ejercicios fáciles en clase y en los quices pone un montón de ejercicios y difíciles, es buena persona cae bien, pero hay mejores profes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'f119e59b47a7eed84348398f768bd6cda0058cc8c64ef319868a02353f37efc6'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Divaga mucho en historias y anecdotas, pero es buen profe. Siempre muy dispuesto a ayudar, aunque no da muchos ejemplos, usted tiene que ponerse a practicar y llevarle los dificiles a consulta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '26342a74e9697043615936b62fd33f02ec6ce720fe99254b59f781b17707f323'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Si es por primera vez lo que lleva el curso lo evitaria, pero de ahi es muy bueno, ayuda a entender aunq no hace muchos ejercios y da como el ambiente de seguridad de preguntar; pero la catedra es la q se pone feo con los ejerciciosy el profe no hace de tanto nivel .'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2024-11-18T00:00:00+00:00'::TIMESTAMPTZ, '324c7da7c4c94f98f709129a7faa64eb0d96f29b3127662c6af9334525f43b8a'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe es super pura vida. La gente que dice cosas malas seguro le fue mal. Explica bastante bien, paso a paso y se asegura de que todos estén entendiendo. Evacua dudas de semanas anteriores si es necesario y acepta cualquier método para resolver ejercicios aunque no los haya enseñado él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, '21518caf7ef112b8f3b038585f946c7e0c839547db9bbad116cb05beaf2d9efc'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '94501a16b12952bb3e522445f7e588b4cb0181a9724ffd92af41c87ed14888dc'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Da buena clase y aunque su se desvia del tema de ven en vuando ayuda a que uno entienda y da cinsejos a los de primer ingreso la verdad buen profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-18T00:00:00+00:00'::TIMESTAMPTZ, '36b7e5197de411dbc1c5df35a96e4e48e2f44c24de6a63600e3c8cd93ffef956'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El mae es el mejor de la Cátedra, a veces sale con historias y se le va la clase entera, pero a la hora de explicar, es el mejor, da puntos por procedimiento y se preocupa por que entiendan los estudiantes, estudie mucho, vaya a consulta, si le cae bien al profe, pasa seguro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2024-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'f35fcd5d3cd97a32ca7a3c25a1c1ad5f1a760ad0a85d159724c8c47b62f58d2c'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Buen profe, buena persona. Presten mucha atención a sus clases, y estudien en casa porque los exámenes de cátedra si son dificiles. El profe alienta a los estudiantes a pedirle reclamos en exámenes que sean JUSTIFICABLES, si de verdad lo necesita para pasar, le da los puntos. 8.5/10'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9af04b34912c120a14c261dbc2ae3a3917210fca75b8059994cf1e95aab9986a'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'De los peores profes, si lleva con él mejor vaya estudiando porque no va a aprender nada, quices difíciles y explica como 2 ejemplos de cada tema, puede perder 1 hora de clase hablando paja, busque otra opción y aunque aquí digan que es buena persona, como profe no sirve'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Da crédito extra']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '197880e973e9ba5f4c97e9c7a09f4f82bcb5002ebeed33009a2c577ded3de64d'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd273a2ef5926aca608728b9dd847f7de8eef6961f95eceae7d1ae2b6f57f3cf1'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Las clases parecían de religión, tomaba media hora para hablar sobre ello, cosas que no aportaban al curso en lo más mínimo. Hacía comentarios sin gracia y fuera de lugar. Es muy desordenado a la hora de explicar. En cuanto a la facilidad de curso, si es verano llévelo y estudie por usted, listo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-26T00:00:00+00:00'::TIMESTAMPTZ, '27ad3b07c015d832d0de557d84c671cdbded4fd84733bbed4b2b8f467e6f2995'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Muy buen profe, explica excelente aunque muy largos los ejemplos que hace en clase, siempre dispuesto a dar consulta y revisa muy rápido todo. Volvería a llevar con él. Está Cañón.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2024-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'fdc038168d131a7948563f718a8f0a6e7a27e9fc5efbc154559ec1377c02860a'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profesor habla más de lo que explica en clase. Trata de ser muy pura vida contando chismes o anécdotas, pero por eso se pierde la mayor parte del tiempo (DEMASIADO). Cuando le da por explicar la materia sí se le entiende.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '05197349921c27bf759cef687b7eaf8b5734e04a892bf38b6dfe964f44c2c9c0'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El profe te ayuda, hace el ambiente sano y no te deja presion, es el mejor profe, si algo no te parece el esta abierto a ayudarte y con gusto el lo hace, no como otros profes'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '1a6bedcee2f623dc4616135b1d581864a595ba46262a33b3ddb34e412aefe2f6'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'La gente que lo califica bien es porque confunde ser buena persona con ser buen profesor, son cosas totalmente contrarias. Es buena persona, pero como profesor no sabe ni en dónde esta parado.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'a1e88da7b3457a4d500fb459152f4dbfd7c53b8218e482e660616896eb954ac2'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El profesor en si es buena persona, pero no da la clase. No explica los temas y en una clase de 3 horas, hace dos ejercicios y el resto de la clase es el contando historias o hablando con los estudiantes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-07-27T00:00:00+00:00'::TIMESTAMPTZ, '64d7b2d9975b75ad84f7a1daef1da1903a26359d12843f5c79cfd295aac09fcc'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Regular, habla mucho de religión, le gusta enviar mensajes a estudiantes, cuidado con eso, es mejor evitarlo, comienza hablando de Dios y termina por otro lado, son cosas con las que hay que lidiar y andar de largo. No recomendado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Requiere mucha lectura']::TEXT[], '2023-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'dabda9ea93707c6db2deec98b79c5b9cfcbac22b63e21ebc2d41db5203c3777b'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Pasa contando su vida personal, en 1 hora de clase hace un ejercicio, sólo hace las prácticas semanales, explica bien pero no lo recomiendo para una persona que está llevando el curso por primera vez'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '190e8322f4f5df71e7273d5f22e7e3a982c72724b58ede2c9fc5e9c3de114b97'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Como persona es muy bueno y divertido pero como profe es pésimo, las clases son resolver dos ejercicios de la guía semanal de la cátedra y el resto de la clase es escucharlo contar historias, chistes o hablar con otros estudiantes. Las clases son una perdida de tiempo, el curso se vuelve autónomo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd67355ce17f54b9778bffc88e1e660d86675eaac85e26bacb1b28caf7d20633d'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Es de los peores profes del TEC, acepto que es buena gente y hace la clase cómica, sin embargo, no sabe explicar. El profesor tiene mucho conocimiento pero no sabe transmitirlo, las clases son muy aburridas, no se hace nada o se pone a hablar sobre religión.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e1965ad2e55a566c92b4b46d0b53ffe21b36a864efe67ff86c841cd39a0b9f9e'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Sus clases son una perdida de tiempo, habla mucho y no explico solo resuelve ejercicios de la práctica semanal. Debe tener buenas bases para entender todo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fe742abf35d8adac8d246cbb442eac4d174314b0841507bd3de199fb3411a4fc'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Este profe es excelente, es súper comprensivo y sabe demasiado. Sus explicaciones son muy claras y trata de simplificarlo lo más que pueda. Habla mucho, entonces sus clases no son nada aburridas. Lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-24T00:00:00+00:00'::TIMESTAMPTZ, '57ab52b2376a33af0bcd5468624fc4f5e84c43b33cb2d4d0221eb9b1dfd0ed61'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Es una excelente persona, y como profe sabe explicar la materia, pero a veces pierde mucho tiempo contando historias (no hace las clases aburridas). Como recomendación es que vean las guías semanales y hagan los ejercicios antes de las clases y que estudien con el libro que proporciona la Cátedra.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2022-12-05T00:00:00+00:00'::TIMESTAMPTZ, '9af176256fe3bce1b3f37dbbecddd0f58c3444d206ef32f6c45a4a0b1e76e83e'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Un profe muy muy gracioso, le cuenta toda la vida aunque a veces si pierde mucho tiempo de clases en eso. Se enreda un poquito a veces explicando. Los quizes hechos por él son muy duros.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c60916d75ff47a319b431ab2962bf7a2fc42344a955f1ba948c8e0daecb17c95'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El mae no es lo mejor para explicar, si ya usted le sabe al curso, pasa fácil, pero si no, es complicado. Haga las guías y saque dudas. Tiene un punto de vista religioso muy marcado y lo menciona siempre. Si usted lleva dudas, sí se las aclara, pero no es mucho de dar ejemplos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'bfc33f5d31970afb8b43dd87613b8a30d55e1583eb9543a864913ace4157d891'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Muy buena gente, sabe mate, pero como profe la verdad, si puedo evitarlo no vuelvo a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'd70e5da6982c9e9e9a14a78bd34f07279a811172c80a0904e358bac727f3d5e0'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Es muy pura vida. Siempre tiene algo que contar y eso hace amena la clase. Eso sí, haga los ejercicios de las guías semanales antes de la clase para que no sea muy difícil entenderle. Los quices que hace son cortos, difíciles y de mucho porcentaje. Si no es muy bueno para mate, busque otro profe.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-05-18T00:00:00+00:00'::TIMESTAMPTZ, '1f79b1529fa84ab5dc304084aded5610bfe81f6f43a013b55fa527c9fd655e5c'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, '685570f0b1bd6f3ebb457f60b8696dd681b697892b83e792921c0e8781f633e8'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es un acosador y discrimina a las mujeres por ser "mujeres"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, 'f0943bf3613f5e827b4c588067f5531063a4b35d6fa3b1e358a63791958a9103'::TEXT, ARRAY[2439]::BIGINT[]),
    (501::BIGINT, 'está cañón'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-24T00:00:00+00:00'::TIMESTAMPTZ, '3a8aff0c6ea11d5b408ded8d082dcb05fc22c31a40d9a9f3268fccba9de102e7'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El profe es muy pura vida y siempre está dispuesto a ayudar, pero los quices hechos por él son bastante difíciles.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '903d694dd70a4dd1e1e32252435537b7712173172ec22bfe7dbeb5a389f3a8ac'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Las horas consulta con él son muy provechosas, explica bien y es atento. Solo que un poco desordenado en dar clase, por eso vi las de otro prof. En resumen, si quiere matricular hágalo, sería un curso muy autónomo y si usted no lo es mejor no lo matricule.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'e499fd4634f590be795bf1b9e37872d68cd36691474131bd5e7361e34dbe8ab2'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es buen profe a mi parecer, se preocupa de que uno aprenda y siempre está dispuesto a ayudar en consulta o en clase. La materia en sí es difícil entonces hay que estudiar bastante por cuenta propia. Los quiz que hace en el GAAP son de 3 preguntas por lo general entonces cuidado.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0770d779c24f2d7ce2565b570e0ed228fe38a6fe58f05df0c7999fb32aae6936'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '28cbf458681623a5e0729c881d4d2f2316ebcf535ecab87a682f46f7e8132b1e'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Bastante confuso al momento de explicar. Pero, la verdad en la actualidad se puede meter este curso con cualquier profesor. En internet existen excelentes profesionales explicando éstos temas La educación está cambiando y, las clases presenciales serán muy pronto un pérdida de tiempo. No lo recomien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '6cac14670c340982771acf3717cb8a44778d2dc48829ea2397378ce7a655ce84'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0c1d9682bd8da0a16b97e519d82f35ed620877e3d723bcb4357741f2dfda7f9f'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Como persona es bastante bueno, pero como profesor en modalidad virtual no es tan bueno. Da la impresión que a veces está como perdido con las evaluaciones. Este semestre él no tenía claro la distribución de los quices/tareas y dejó como 4 quices de golpe al final cuando pudo hcaerlos antes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '734b749d88d229edfbadfad8e74b93d5c4a177d5f250b877aadb9b77dd472ac0'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Casi no se le entiende. Es un poco enredado. Pero, se pueden apoyar con YouTube o libros. En lo personal no me gustó, muyyyyy flojito el curso. Si pueden metan con otro.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Requiere mucha lectura']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'f921cbd7b155d2acd45d1c4193fd7aa2cf33db4a98c798f17b48fd9ed2d41470'::TEXT, ARRAY[935]::BIGINT[]),
    (501::BIGINT, 'No es hipócrita, no le gusta el sindicato, no invade la privacidad del estudiante, está en forma, no molesta al estudiante con mensajes de WhatsApp. Como profesor.... En la actualidad existen herramientas como YouTube con excelentes cursos. No es necesario un profesor en línea. Mucho gasto público.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases largas']::TEXT[], '2020-12-26T00:00:00+00:00'::TIMESTAMPTZ, '74381e46529810087605786a1036cd151b7d128c2f828d8afcc2b1bc61072e05'::TEXT, ARRAY[935]::BIGINT[]),
    (501::BIGINT, 'Muy buen profe, resuelve bastantes ejemplos y dan consejos y herramientas para entender mejor la clase, es divertido dando la clase sin embargo, divaga o se distrae algo facil cuando un problema se pone dificil'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, '4580f946e897732325135533501786ab1b50d7ec744e35f3b229a2a53d9835cb'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Él es un muy buen profe en clases PRESENCIALES. En modalidad virtual no meta superior con él, él no explica la materia y lo que es como consulta. El GRAN problema es que la Cátedra de Superior no sirve para nada y sus guías son pésimas, entonces se necesita un profe que en serio enseñe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, '21fa8be8f518cbd01656bdf2865de96602bf8d45bf6f0a2ece767a0b47939742'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Súper gracioso y súper buen profesor. Apasionado por su trabajo y explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '3d41ff6d2632774732814c871d63dc54e33d6099933b330ebc55db2df2146a98'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Es excelente, tiene una buena metodología y pedagogía, le gusta lo que hace, se preocupa por los estudiantes y que se entienda muy bien, las clases son entretenidas y se pasan muy rápido. El curso se pasa bien, si se práctica, hace muchos exámenes cortos y si él ve el interés del estudiante ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '2a3f144aa7853494c61e727a5f54dc54925ea221265e53115f4ba3427ee3cf31'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Llevé presencial con él y nunca había disfrutado tanto un curso en mi vida. Se nota que le gusta lo que hace, explicando no es el mejor pero se entiende bien. Hace las clases divertidas lo que es raro para un curso de mate.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '1da5dd21a5b05d431d8db6896bc66734bd5f86daa9c60a8317b09f05c3c5f5b0'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Simplemente no se los recomiendo, siempre trata de perder el tiempo en cosas no importantes. Es muy buena gente pero si tiene otra opción mejor tómela de verdad!!'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '6f4cf7e9c0aa6a5db146d01b08de536511707d67c5d2304e2a236c88027fdc5f'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (501::BIGINT, 'El mejor profe de matemática que he tenido sin duda si matriculan con el les aseguro que pasan. Ademas de ser un excelente profe y ayudar al estudiante, saca tiempo para contar anécdotas lo que vuelven la clase entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e947803a1c92ff4f89e5beee874bbfc02461bc8c99d930f8447eae5be19b56fd'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (501::BIGINT, 'Es un buen profesor pero le falta respetar a los estudiantes, es muy machista y hace chistes burlándose de la capacidad de las mujeres. Además de que suele perder mucho tiempo hablando de la vida sexual de la hija e incluso la de él mismo. Si tiene otra opción, mejor matricule con alguien más.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e9c7f50306215aac3a65a89b402d25d9f62f9be15affb0ca466695b1553729fa'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Es un 100 como persona, pero pierde un montón de tiempo hablando, califica suave, le gusta que participen.No siempre el hecho de que hable lo veo como algo malo, solo algunas veces que si se pasa mucho, pero por lo general hace menos cansada la clase, es muy chill ir con él, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'be54459983ec189065ae4cd91e892b90539689d489dd5e14cee34ff2a72c8be3'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El curso es bastante fácil, por lo tanto se puede pasar con ayuda del libro, que es mi recomendación en caso de ser autodidacta, pues el profesor suele perder mucho tiempo en clase, ya sea en tiempos muertos, buscando algo innecesario o contando anécdotas (esto puede ser positivo).'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '841ed5546ab409f2d95f73ec5bb3f3dc5de48b85b4d166e073f32872f3ab8e4a'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Podría ser un profe genial, pero pierde DEMASIADO tiempo de la clase. No es raro que medio explique un tema a la carrera y copie un ejemplo del folleto y el resto de la clase pase hablando. Califica suave, pero para aprovechar este curso se ocupan clases completas. Se pasa pero no se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '17b4b13fd691a07161137427400d97b0024f5c1b637c43223cead0d5de8e5213'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Es muy ordenado, explica excelente, mantiene a la clase atenta, a veces cuenta historias muy cómicas e interesantes, siempre ayuda en consulta y califica los exámenes muy rápido.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '07f24bee99accd8d65a980c1290cfed144ade689011b977a135a43032608525a'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Gran parte de la clase son chistes y hablar de la vida, pero eso la hace menos pesada. Es muy bueno explicando y se interesa por que todos le entiendan. Practique las cosas que ve en cada clase, él no puede hacer magia, el curso requiere horas extra y compromiso. Por algo es un colador.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'ae593536a3438ceba26fb17ea3a064110ba694323cec898d00474de18a93fb8e'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Muy buen profe. Explica todo de forma clara, y hace varios chistes en clase. Apoya a quienes lo necesiten. Lo único es que a veces puede ir rápido explicando, pero usualmente ayuda a quienes no entiendan a la primera.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '70aaefea6ef72f1f0f537e7a42f66892ab0c861dcbd8c40c9c0a5805bbbaee07'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'En general es muy buen profe, es gracioso,a veces sale con buenas historias, la materia no es fácil pero el profe hace un trabajo decente para explicar y siempre hace centros para repaso. Es una persona muy conservadora, los mas delicados podrán sentirse ofendidos con sus comentarios.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-25T00:00:00+00:00'::TIMESTAMPTZ, '046da7e1af6bdedd8bbcab743be8aebcfbebe6e85d9c8f59a638c98bbb00b626'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'El explica muy bien la materia, lo único que a veces no me agradaba es que perdía el tiempo contando historias transversales, pero a pesar de eso, se aprende y es excelente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'e6e6f32fabf14970a12a00e4cbb078a8d191918f17c37bd88e757e0a7d84297f'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Es el mejor profesor del mundo! Califica suave, ayuda mucho a los estudiantes y hace sus clases muy entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, '3fc1577067c3e7cebcb8bd7b93053c8ae16eae5ee4617d5c40ea8fc6956413e5'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe es un 100 de persona, siempre sale con temas graciosos que hacen que la clase no se vuelva aburrida y que hasta den ganas de ir. Califica súper suave y siempre da las notas rápido. Lo recomiendo mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-19T00:00:00+00:00'::TIMESTAMPTZ, '587e9d6075c574ee972b1c9a5e6cf013ef10df1584ab8ce147db8e0c5e0e4b3e'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe prefiere las tareas que los quices, le gustan los temas transversales que ayudan a distraerse entre ejercicios, explica muy bien y ayuda al estudiante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5452193d280b764d96bfeebdbb0b0e4f370ab541f1d43d714db24e384ac6978e'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '895dc197a3a91c9562deff5e480a88ffb673f173a944c8059968a88d93d783dc'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El profe habla muchísimo y muchas veces no explica lo que debería por estar contando historias... una vez le pedí ayuda y me terminó hablando de todo menos la materia'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-26T00:00:00+00:00'::TIMESTAMPTZ, 'fdcfe17b2bff089f2ee035b079028e9d3a1175420c7ff87aa4fde73e13745784'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Es súper tuanis, muy gracioso pero si pierde bastante tiempo de la clase hablando de otras cosas, esto puede ser bueno ya que aveces lo utiliza como descansos entre ejercicios para no fatigar a los estudiantes con materia. Califica muy suave y siempre está dispuesto a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '25543768832b46b546c1e04b20e4bd27abff2021ee6a89301b18beb1d5fc9bd7'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6ed1dcb41c36977b2d934f2e13852c7277833fd95e070c08febc8739e6fd5552'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'El profe siempre lleva un tema transversal que nada que ver con la materia, se pone a hablar y se le olvida que esta resolviendo ejercicios. Pero como persona y como profe una teja, casi no hace quices, solo tareas, eso ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2281499e8315c17ea1fe70813e1054ce87ddf8dae079cf4734e9fa07d9cedb33'::TEXT, ARRAY[1034]::BIGINT[]),
    (501::BIGINT, '10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e54cfb978e4685046bb692d1c8fbaa61249a3c1175d50b70a38103d1212244cc'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '74d5e0f9678b6831f0286aacd08fc5f889ed3d6ce01a88eadf34f7da4140abe0'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Muy buen profe, habla de cosas fuera de la materia pero hace pasar ratos agradables. Ayuda mucho al estudiante y pone ejercicios cañones en la pizarra que en ocasiones le cuesta resolver. Pero muy bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a5526a0e6a21c148a7dcc5dff5f8350c9c783cb3681f35fd46a441f63938f205'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b15cc7cbbd3134fc67eb81ccb5c9272efbb4cae9e85e547610e032af4c24c317'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Explica bastante bien y ayuda mucho a los estudiantes, califica suave, pero se desvía mucho de la materia y se pone a contar historias y se pierde mucho tiempo, pero en general es muy bueno.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd9d4632b2f267900f19d20b7fad9c7ccd6a947f651ae3627a83996ffd3e68c06'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Muy buen profe, aveces habla mucho de cosas nada que ver pero igual da la materia y es muy claro. Siempre intenta ayudar a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'cd8a815a55c4b41acb8c933c6ccab8f42c16c2723499257abf72f97f3312988c'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Lo recomiendo totalmente ????'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c6a692f385b6e2bb611bff6759220d5ea8734810bcbbf2eddc41b0640d6696e1'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, '11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ee61a3c6c7642395be4b04cf36e3f6e9d7a0c287b1a7deb55ee42fa33b945546'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Una teja de profe! Se enreda un poco pero sabe muchísimo y le ayuda demasiado a los estudiantes. Explica bien'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-06T00:00:00+00:00'::TIMESTAMPTZ, '937fc6082d6174b0bf06bd5f2383419b01eef239a60d3f6775d32da5c5b34cce'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Se preocupa porque lo estudiantes aprendan. Las clases son comiquísimas y hace ejemplos muy claros. El mejor profe de mate ?????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '3546580f4d33c9641fdd2b64c771c77b41e70541aad4c7e6f4d3bb28412b5f87'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El profe es súper tuanis pero aveces pierde el tiempo cálifica súper rápido y se entiende'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, '7808100b05e7adca2a9a316200719152d501760eb2c59b45b19742807db82d7f'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Buen profe, cuenta muchas historias pero explica bien. Ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'bf0befa08af53274b5fe27918194e9dca9ec5c6a7931deb0f3dea28fd5553fb6'::TEXT, ARRAY[1041]::BIGINT[]),
    (501::BIGINT, 'Pierde mucho el tiempo hablando tonteras, a veces se queda trabado explicando un tema o atendiendo una duda'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-26T00:00:00+00:00'::TIMESTAMPTZ, '4e3ae2ca7aa6c6237e47fc3f857bdcbad84c40546b91bc5dcf36c9c7c4dd0213'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Pierde demasiado tiempo en clase hablando de cualquier cosa menos de la materia. Califica suave y busca ayudar al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-14T00:00:00+00:00'::TIMESTAMPTZ, '4c925d560286527ba00c9fa31ff6541d03fb192e1fa9041a3b44dde60fedf48a'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Pierde mucho el tiempo. Califica muy suave y ayuda mucho pero las clases se pierden y casi que hay que aprender solo.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-04T00:00:00+00:00'::TIMESTAMPTZ, '2ba72d0bb25bafb65becfd025f841c098ea9ac792f8f663e98f27a52b3686f26'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Buena persona, pero mal profesor. Muy desordenado, con mala pedagogía para enseñar, pero lo especialmente malo es que las clases no se aprovechan, dado que pierde mucho tiempo. Un curso donde no se puede disfrutar la materia por culpa del profesor, dado que a veces ni las ve.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura']::TEXT[], '2017-08-09T00:00:00+00:00'::TIMESTAMPTZ, '40f0563821565c06bfe01392e90d900913d692df6b816dd51be9eb3de0304ce8'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Explica muy bien la materia y es DEMASIADO pura vida. Por lo general se desvia del tema y algunas veces se enreda. Pero en general lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1702c0249ebaf9900cf561ddcb317efa0f5315715dd4e435482878a9bd9232d4'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Cuando dicen que se devia del tema ES ENSERIO. En una clase puede pasar la mitad del tiempo hablando de otra cosa lo que hace que no se entienda la materia muy bien. Explica bien pero yo no lo recomiendo, un desastre'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd54528eea4c9b9d0107ed6baedb09bd21201e4db94d4bdc280f5fc2be66fb41e'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe ayuda pero debe ver que la persona se esfuerza, ademas pasa parte de la clase haciendo bromas, pero el explica muy bien, tanto en clases como en las consultas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '074f90e0cc5bf532057464d08fc226244f80372d04e9bd91f1c4d66d03e3a6e3'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd2b33e9213f0102f7ba1892def888fa8794a6209541353981c533117b8f14236'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Se desvía mucho, pierde mucho el tiempo y se desaprovechan las clases. Califica suave y ayuda bastante pero cuesta entender porque hace pocos ejemplos en clase.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '356de0d36d730cf7e20c89a7148e8bd44db41d8c431f1f1da0a297fa43103264'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es el peor, se desvía demasiado del tema y habla más de sus anécdotas que de cálculo. No lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'cb3859bc82bf7e84e715f6cc72e43bd02449dab7b6172825b0b8e5ba21e2b094'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe es muy buena nota, solo que se desvia mucho del tema, por lo que explica 1 o 2 ejercicios y ya entonces a veces uno no entiende mucho, califica normal y los quices son un poco dificiles, la verdad no se si volveria a llevar con el.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, '70edf97f1cb87897694aba1e311461453b9eb67083a40a9aaad40ba6510ca876'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6e285be026fc9bae009893a0e72356070833c3595566d606a188f09a7a17ac4e'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Muy buena persona, te ayuda mientras con muchos extras, como tareas o asistencia a rama, pero suele desviarse mucho de los temas, y cuenta muchas anectodas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '683ffbedddf004f24a0016e154bb13c8c1efc60e0fdb54ecbd3bb4ba7d09068e'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Explica bien, normalmente habla bastante sobre otros temas ajenos a la clase, es demasiado chistoso, aún así no se pierde materia, y sabe que temas debe explicar más, por ser de mayor dificultad. tienes que practicar bastante fuera de clase, pero califica muy justo. Excelente persona.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '85bd40b833af4b8becaaed72d0b965bfcb5094eb87f406c707c765d6bbda81a2'::TEXT, ARRAY[2439]::BIGINT[]),
    (501::BIGINT, 'Se desvía mucho del tema contando historias que no son del agrado de todos debido a sus creencias y lo "religioso" que es'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '397c7460e9dfd3d7c693dab47b3779d1e8d2a42412b8781aa403a253fee6014d'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'El mae se dedica toda la clase a hablar de todo menos de la materia, meter un curso con él es la pérdida de tiempo más grande mejor estudie usted solo. Nunca más en la vida.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '406c4f13bed0021ee6a4a59295e0aca7abb1ba81f0d517efb5973c3005577560'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'El profe explica de forma aclara, la clase es amena (a veces se desvía del tema, pero no se pierde materia), explica hasta que uno entienda y califica suave'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-05-26T00:00:00+00:00'::TIMESTAMPTZ, '04ca1cd99c4964705a94c9583385cc77f65093095cdd4d75f05944d81079ad79'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'A mi parecer no explica nada bien. Despues del primer parcial, todo es a pura exposicion, por lo cual menos que se entiende. Califica suave, lo que podria compensar lo mal que explica, pero no se aprende nada. Discreta lo lleve porque no sabia y Calculo porque solo el estaba'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-13T00:00:00+00:00'::TIMESTAMPTZ, '66882d9ca4d8ad686845ab733e25f54345565cf7ff4ba5ae585a3e500044a587'::TEXT, ARRAY[1018, 605]::BIGINT[]),
    (501::BIGINT, 'Lo recomiendo pero para mate general porque es fácil, habla mucho durante la clase'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'ee91c228c8623379900878091f9ced3ce1b4068173126369035a6ecaa97ab2a5'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Pone a los estudiantes a dar la clase con presentaciones, y se excusa diciendo que son quices. Él no es malo, enseña bien, lo que pasa es que es demasiado estúpido, sólo pasa contando chistes tontos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-26T00:00:00+00:00'::TIMESTAMPTZ, '5e232d308d0d93237f8398b8af48b9e8620a077761d4cf3d84c9044597363145'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (501::BIGINT, 'En verano hace exámenes matadores, pero los hace de bastantes puntos para no joder al estudiante. Califica suave y las clases son muy entretenidas. Excelente persona...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, '98ac419625c2b3c4329f3d7bc6a73f976c670ea901d46272bbd17397b0dcce22'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '2c6279fb9ab67be9bf3bf23a05754d0635a84c62aeba3f763f77e3b5df1511a0'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Se tiró todo el 2do parcial a pura exposición, dejando q los estudiantes dieran la clase y al final se lavó las manos prácticamente, uno esperaba clases del profesor no de los alumnos!'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'bc3bead2493962a0268becc13db6dff2eb0e802ea1d1886774d3de787dc403ef'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Excelente profesor, sabe explicar de forma clara y concisa, tiende a llenar la clase con historias que suelen ser divertidas (las clases se vuelven amenas), califica muy suave y aboga por los estudiantes. Ayuda en lo que se pueda y comparte bastante. Excelente ser humano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'd8eb9564aa81f7abcb6f2ac6a2df364f895b99af1f32edab77a76f11b33f7770'::TEXT, ARRAY[563, 1018]::BIGINT[]),
    (501::BIGINT, 'Buen pedagogo y buena persona, muestra gusto a la hora de dar clases, aunque puede distraerse para hablar de otros temas ajenos al curso. En relación con la materia da lo justo y necesario. Al final, como diría él: "Very easy, piece of cake".'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'c67bbcd4f1aedbc522b9ed7ebdd204668892e5cb343bf7fa88e20996152a9eb4'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4f477f7997c2cc841531be566ae4fc0b98f16b18dfeba9dcf58245fd4e1a4644'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Una teja de profesor, súper recomendado. Siempre anuente a ayudar con las dudas pero uno tiene que poner de su parte estudiando en la casa'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '80d90217f29a5a8e5f4725b3430d770fbc8abfe476c6f3e0954a38353ec4570f'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5949c45263c25b0b91b1bf918179ef0dce0eeb5b1fd73fe7470c0f4b3c7eb7c7'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd2d184491ba024f733c2fb89b0975aa9ab4052425d4c03cb3e04d5d080ccbfd4'::TEXT, ARRAY[4466]::BIGINT[]),
    (501::BIGINT, 'Excelente profe, siempre esta dispuesto a ayudar cada vez que usted lo necesite, y las clases son muy dinamicas, teja tanto como profe como persona 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '14afa8d699d3da47a83c081976369684eea14b5481d95cd4f86de01f212e8968'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Excelente profesor si se estudia como se debe en la casa y no solo el día antes, la mejor opción para Discreta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '36c27f1f333ac8ae3314fc936148d2eb0c3aa8a84306dc29315740d16ff604d9'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Una teja de profe, nada más que decir'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'b90fec0c0f4f8391e73fc6bc4d7fa91337313dfdf8607d988d6739cb92c98986'::TEXT, ARRAY[1041]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-03T00:00:00+00:00'::TIMESTAMPTZ, 'edd8a025310e095dbb731a7e1d89dd714de339a52d8b06db5c5300b0baf9240a'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Se debe llevar la materia al día, porque de lo contrario lo único que uno llega a aprender del curso, es un puñado de anécdotas del profe (cabe aclarar que es muy buena nota).'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, '4a4e87f8a87360e15db35fb6a2050a1e757187d7711a6cc40a32227fd8db65d6'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Habla demasiada para, mejor se devolviera a dar clases en los colegios, si tanto le gusta.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-09T00:00:00+00:00'::TIMESTAMPTZ, '07b91ae8999bcbefb80ea332eeb078e9bc428a1048d01908094752bde02c721b'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Buen profe'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '303fa999ceea534a4d9248138a59b0dae720701ab7b8a66c911dad7879f9a69a'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Muy buen profesor, explica claro y se interesa por la comprensión del estudiante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '24c2166e6b69f75db5857fff1431743e364c4f4550198e03d378db997c87a19f'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'es un buen profe, explica muy bien aunque se distrae un poco con facilidad, pero lo compensa en la forma eficiente de aclarar dudas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7d2046bb9d09860461507edbdc191f35f6f9dd932c3adb6e95499e91b7d8434f'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Habla mucho en clase pero sabe explicar y si uno pregunta le aclara todas las dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b758ca8d7924b63f5ccc8ce15def0d33c7fc3207091f63b6475aa8c2c016970c'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '24b7c5487dd1b541686aa695c2dfa54a289de1da41b725a174963ce7691634d5'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Pierde demasiado el tiempo contando historias, no se enfoca en enseñar solo en experiencias de la vida personal. Esto perjudica mucho a la hora se realizar los exámenes, a pesar de que califica súper fácil. Los exámenes son colegiados, entonces no se prepara bien al estudiante.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '84423e1a00616548a881ec48922ae81e89f49902a91914705b988d6a5f35074a'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '462ed30adae9732c1550e52af3b0a6da9baefd31e5ec1667fec09bee3527921d'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'd4ced727f7586bf42c70c88ecf99a6bffdb9e7b459c12483abab830ee3a15e05'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Recomendado! :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c26d95b7b70cc664da86ebe8a8ae557fc0a970a7face7c0f296384810e4636ec'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Gasta demasiado tiempo contando historias y anécdotas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ab752ae1a64a7999a585474589d2fb8eb46e9996f196f4ccdda7c559dcde57c3'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '983eee84dff2831f28e1727a180b45054b90b58e2f95420e7ce2735e796e1cf4'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Pierde demasiado el tiempo, llevé verano con él y fue como ir a recibir consejos de como ser millonario y ser exitoso, y resolvia uno que otro ejercicio, claro pasarle fue fácil'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '846868ff49bed87e40658df795ec71c93907467d526b46faa064b128fbdecc1c'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'eb02683680afbc495f00513098400a1feb6fdb4de6951d7d54cb90ed4084e286'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Excelente persona, solo a veces gasta mucho tiempo contando historias'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f2ad5c4e545aec076d7272243f6cce70b2f47d0f74101f1f9ad1583819dfc78d'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Explica en clases muy bien. Hace un ejercicio fácil, uno intermedio y uno nivel examen por tema, como mínimo. Los quices son fáciles. da pistas de lo que va a entrar en el examen. Es uno de los profes que dan a los estudiantes exámenes resueltos para estudiar. Pero eso si tiene que habla mucha paja.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '61bc49773abef2077a99ad5d08aab990d233cc25ef5ab435d4245d6a741b481e'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Sabe explicar muy bien, una teja este mae'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'eea1e6c6011b902eaddcdfe5053abca5786ac194e6694ab235652a00f14c18d8'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '75500a749821e10023dd1e2569749d8ae52fa622460961ae10b8fbd17591c210'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (501::BIGINT, 'habla mucha paja'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '55e5dcb9deb4a3fbcd6a9734c995d9aa544c94cea90fde230161e76c36081620'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'En clase es bueno, pero si uno va a consulta es muchísimo mejor. Como persona es demasiado tuanis.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '429052a7d28dc8a8c05b2c593640cf1eaae723cad4dce01a7a4be2b121e711da'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Es mejor aprender del libro, aunque el mae es muy tuanis. Lo de las clases de manejar el dinero es cierto jaja'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '25939b6a5a9485d71d26d02ce9b426ec1abd305afb5d9c2e68de160b7657fcf9'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Ademas de matemáicas nos enseña sobre como manejar el dinero en la vida, excelente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '518aa1742ec3defd43c3ae175e9e3d70ca53619e3f47589019a5284dd214cebb'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Muy buen profesor!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'ea02e35aca9ee9f94690a3c42239b0a612ccc08102d8891247627ffdf151149f'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Requiere una investigación interna y procesos disciplianrios. No hay denuncias por miedo a represalias. Todo mal con el TEC.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-11T00:00:00+00:00'::TIMESTAMPTZ, 'ef50f09aad687847a3c86ab78a9d01e29fb9443f863679cea196d520932c31a2'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'El mejor profe que he tenido en mi vida, sabe mucho, explica rápido y super claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'dce69a0812bded6691b810bd1befefa846d510b4cc24c7005868162b7e7f74cd'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'El profe pasa hablando casi la mitad de la clase pura paja. Los ejercicios que hace en clase son siempre los más sencillos y le da pereza explicar los más difíciles. Los quizzes son difíciles.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-15T00:00:00+00:00'::TIMESTAMPTZ, '7dbc7367964482e8d423b1162eae1a09b95cd436dba109c78c51b6cfff6321ad'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'De 3 horas de clase, 2 horas y media van destinadas a hablar de lo que se le ocurra (generalmente de religión y su pensamiento político). Es homofóbico, transfóbico, acosador y muy extremista y cerrado con la religión. Si piensa matricular con él, no lo haga, está por cometer un grave error.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-05T00:00:00+00:00'::TIMESTAMPTZ, '70dfd619ba5c975111ff0d7c614945ec12f2d6fd45bf454193d04b55b731075c'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Es el mejor profe que he tenido en mi vida. Completamente claro y muy muy divertido. Jamás en su vida haría un comentario inapropiado o despectivo a alguien. Recomendado completamente. *Favor leer con antónimos*'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, '2c30c231a95fe7de0017d02e50e85a2f1cd24c91c92cb2a485474bf3b75c5862'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'sus clases son muy buenas, ademas es muy buena gente entonces las clases no se hacen para nada tediosas, generalmente explica bien la materia y es claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0e5552a5ba58175babef3c7ca03fe7cf71fb214d6cb8672712e5083d119ac65c'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Cálculo Diferencial es ya una materia difícil donde 3 de cada 10 estudiantes pasan, el profe es buena nota, y da puntos extra por reclamos de examenes o si de verdad los necesita para pasar, las clases hay que prestarle mucha atención ya que son virtuales. Hay que estudiar igualmente en horas libres'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Da crédito extra']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7494facd9cdb124ac59f2cae8d34a71156fc0419b632d7b97d7f4c2d588f9cbf'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Solo habla de religión y otros temas en la clase, la mayoria de veces deja perdido a los estudiantes en su explicación. Es buena nota, pero no volvería a matricular con él.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '16407276f598057ab4d55b4fb7ce9b3b811bfe8e0f59329f9b1f258ee4327ea0'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'La peor opción para llevar este curso, por si solo CDI es complicado pasarlo y con este señor es el doble, se debe ser demasiado autodidacta y pasar el curso por si solo, no explica nada claro y lo que enseña casi ni ayuda para el examen, además los quices son dificiles, busque otro profesor.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'd333e27ef5b44abe700ec1c84fe52a4958212342dd70561bf7877ae9461c38e7'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, '¿Cómo es posible que el Tec permita que esta persona siga trabajando aquí? Es un acosador, homofóbico y, además, no es un buen profesor. Muchos estamos de acuerdo en que deja mucho que desear.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'c538554fa251decbe3c755d7543cfda6d386582adc90fff8dc924de7374e6caf'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'El profesor es buena persona, pero como docente deja mucho que desear. Si usted desea pasar, matricule con él, si usted desea aprender, ni se le pase por la cabeza, porque el profesor es buenísimo para pasar sin tanta dificultad, pero el problema es cuando matrículas después con alguien más.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-23T00:00:00+00:00'::TIMESTAMPTZ, 'eb6d4cde855bbd05a9a4f8cc52fa5418001e6137643b74abec12490d298d9ec0'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Gran acosador, tras de que hace comentarios super fuera de lugar y super obscenos. Es un malisimo profesor, de 2 horas de clase hace 1 ejercicio por hora. NO MATRICULE CON ÉL'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd510ccaac35fd58bf30beeb48d799e97c8b971e72c41a288c5a8d12e5019de69'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'La gente que lo califica bien es porque confunde ser buena persona con ser buen profesor, son cosas totalmente contrarias. Es buena persona, pero como profesor no sabe ni en dónde esta parado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-08-15T00:00:00+00:00'::TIMESTAMPTZ, '1e05bf417a440d13815abf29e9d5726116afc0385d73d449bae9c096e6592004'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'La verdad es muy buen profe si uno se la juega con las bases de mate. Hace las clases divertidas y si uno tiene duda de algun ejercicio el se lo resuelve, pero si hay que ponerle de parte de uno para entender bien la materia. Ademas corrigue los examenes rapido.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3f1f69c98e2222858214dd0422373c13022b13a7b5965f70b22908069c0a697b'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5ec6f9daa6575c7ee44c9a33639eccebfae6405f9797b9d150b02010e7cced60'::TEXT, ARRAY[563]::BIGINT[]),
    (501::BIGINT, 'No matriculen con este viejo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-16T00:00:00+00:00'::TIMESTAMPTZ, '076f2c7fd68354f23f041b359c490dc69158ef7743cf18ba3492b4dbcc7fffb4'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es la segunda vez que llevo una mate con este profe y la verdad no lo veo tan malo como dicen, pero también es que le agarré el toque. Es MUY recomendable ya haber estudiado la guía semanal antes de las clases porque no explica la materia sino que hace ejemplos. Sus clases a mi si me ayudan'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '75d778603c623f79259eee0007149b5bd65763cca340975f3e0046ec694f407d'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es el peor profe de mate que he tenido. Es odioso si le haces preguntas, no explica nada bien, las clases son una pérdida de tiempo con él. Tal vez en presenciales era un buen profe, pero virtual es lo peor.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '4446a1f7edb9b5525f5f67d0cad1670dedc1d982a4fe702207faf4fa419111b6'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'El mae es pura vida, si usted lo busca lo ayuda, pero las clases no sirven de nada, además las guías de superior son muy malas Si no le queda de otra, vea los videos de otro profe'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '16c676ed717d8ef171c7f7bc9d9281ec059852b51eff4c4c736c5cdd96452ddc'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Él es un muy buen profe en clases PRESENCIALES. En modalidad virtual no meta superior con él, él no explica la materia y lo que es como consulta. El GRAN problema es que la Cátedra de Superior no sirve para nada y sus guías son pésimas, entonces se necesita un profe que en serio enseñe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, '21fa8be8f518cbd01656bdf2865de96602bf8d45bf6f0a2ece767a0b47939742'::TEXT, ARRAY[923]::BIGINT[]),
    (501::BIGINT, 'Es un profesor Normal, apenas para los cursos básicos de mate. Es bueno, se preocupa por salir bien calificado en sus estadísticas. Hay que ayudarlo para que siga con su trabajo como profesor. SÍ lo recomiendo. MATRICULEN CON ÉL, fijo se pasa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-11-23T00:00:00+00:00'::TIMESTAMPTZ, '8753af2c22a3d8fe472a0aa3816530ea0c751785a08bd53759c3873e6bd50f1b'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Excelente profesor, el curso no deja de ser difícil pero con apoyos en vídeos todo se mejora. lo lleve virtual, recomiendo ver alexprofe se complementa muy bien con la clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'd81eee60d69b4962817327589f8e2cea7766955fa620cdccdbd4c8c8a4f30bcb'::TEXT, ARRAY[605]::BIGINT[]),
    (501::BIGINT, 'Si usted es de llevar las cosas ordenado, pues no es muy buena opción ya que tiene que estudiar mucho porque el sólo resuelve ejercicios asumiendo que ya sabes el tema, pero los quices son fáciles, a pesar que muchas veces traen errores, vacila mucho y es comprensivo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '4a0503d101110e2691181c18cf414f59dcb07eca4868ebaf01937bcadb108a3c'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'Es un excelente profe, se preocupa mucho por que los estudiantes entiendan y por entablar una buena relación con el grupo. Su personalidad hace que las clases se vuelvan menos pesadas. A pesar que la cátedra hizo el curso asincrónico, él sigue dando clases en las que resuelve ejercicios.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7e0e397a9d2a532e6829f565b0842dfd4092d844070b89a22ffd74c439f4fb97'::TEXT, ARRAY[634]::BIGINT[]),
    (501::BIGINT, 'El mejor profe de matemáticas que he tenido en mi vida. Ademas de que explica de la manera mas clara posible mantiene entretenido a los estudiantes con sus historias. Lo recomiendo al 100%. Si matriculan con el pasan el curso de fijo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4ef590146d93441d4423a3c28b2de7af520c3a9292913952aa0bd413b12e30ea'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (501::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, '356ab5a9c31436c4e43a08ae9527de04b2e6ec58855c123ab79370175a3ee05c'::TEXT, ARRAY[1018]::BIGINT[]),
    (501::BIGINT, 'Mantiene a los estudiantes interesados en la clase y despiertos con historias.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'bf1b4bcdebd399272a760ead1ce4ebcd13c8fd5c00266cae52679f0e92c13e52'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
